/bin/bash -lc "python - <<'PY'
import urllib.request, urllib.parse, json, re
terms=['Branchiostoma lanceolatum[Organism] AND latest[filter]', 'Branchiostoma lanceolatum genome', 'amphioxus Branchiostoma lanceolatum']
for term in terms:
    url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=assembly&retmode=json&retmax=20&term='+urllib.parse.quote(term)
    try:
        data=json.load(urllib.request.urlopen(url,timeout=20))
        print(term, data['esearchresult'].get('idlist'))
    except Exception as e: print('ERR',term,e)
# try NCBI datasets v2 API genome taxon
for endpoint in ['https://api.ncbi.nlm.nih.gov/datasets/v2alpha/genome/taxon/Branchiostoma%20lanceolatum/dataset_report?filters.assembly_source=all&returned_content=COMPLETE&filename=none','https://api.ncbi.nlm.nih.gov/datasets/v2/genome/taxon/Branchiostoma%20lanceolatum/dataset_report']:
    try:
        txt=urllib.request.urlopen(endpoint,timeout=20).read().decode('utf-8','replace')
        print(endpoint, txt[:1000])
    except Exception as e: print('ENDERR', endpoint, type(e).__name__, e)
PY"

