/bin/bash -lc "python - <<'PY'
import zipfile,re
z=zipfile.ZipFile('/workspace/BraLan3_ncbi_dataset.zip')
for name in z.namelist()[:80]: print(name)
print('---matches---')
pat=re.compile(r'BLAG01001237|BLAG04000511|BLAG12101319|BLAG09000943')
for name in z.namelist():
    if name.endswith(('.gff','.gff3','.gtf','.faa','.fna','.ffn')):
        with z.open(name) as fh:
            for i,line in enumerate(fh):
                s=line.decode('utf-8','replace')
                if pat.search(s):
                    print(name, s[:500].rstrip())
                    raise SystemExit
print('no match')
PY"

