/bin/bash -lc "python - <<'PY'
# Source-artifact lookup only: report BraLan3 GFF annotations for selected marker IDs.
import zipfile,re,urllib.parse,csv,io,os
zip_path='/workspace/BraLan3_ncbi_dataset.zip'
targets='''BLAG01001237 BLAG19000852 BLAG02001652 BLAG07000122 BLAG17000160 BLAG02000205 BLAG05001110 BLAG07000022 BLAG01001860 BLAG09000943 BLAG90000717 BLAG18000879 BLAG10000564 BLAG03001967 BLAG12000872 BLAG17000721 BLAG01001123 BLAG01001642 BLAG02000459 BLAG01001695 BLAG02001244 BLAG01001694 BLAG19000003 BLAG07001130 BLAG14000798 BLAG04001719 BLAG03002070 BLAG09000671 BLAG17000294 BLAG12000132 BLAG06001175 BLAG05000660 BLAG18000687'''.split()
T=set(targets)
pat=re.compile(r'(BLAG[0-9]+)_[0-9]+')
anns={t:[] for t in targets}
def attrs(s):
    d={}
    for p in s.split(';'):
        if '=' in p:
            k,v=p.split('=',1); d[k]=urllib.parse.unquote(v)
    return d
with zipfile.ZipFile(zip_path) as z:
    name=next(n for n in z.namelist() if n.endswith('/genomic.gff'))
    with z.open(name) as fh:
        for b in fh:
            if b'BLAG' not in b: continue
            s=b.decode('utf-8','replace').rstrip('\\n')
            f=s.split('\\t')
            if len(f)"'!=9: continue
            found={m.group(1) for m in pat.finditer(f[8])} & T
            if not found: continue
            a=attrs(f[8])
            summary={k:a.get(k,'"'') for k in ['gene','Name','product','Note'] if a.get(k,'')}
            for g in found:
                if len(anns[g])<5:
                    anns[g].append((f[2], summary))
for g in targets:
    print('\\n'+g)
    for feat,summary in anns[g]: print(feat, summary)
PY"

